#!/bin/sh
# TICK-391: the acceptance guide under docs/acceptance/guide/ (the HTML pages,
# the Bruno collection with lib/nava.js and its REGISTERED codes, and the kit
# zip) is generated by docs/acceptance/guide/build/build.py from its sources
# (build/*.py, api/errors.yaml, api/openapi.bundled.yaml). Rebuild and fail on
# any difference, so a source edit without a rebuild is caught.
#
# The zip is compared by its members (names and bytes), not byte for byte:
# build.py fixes every entry's timestamp and mode, but the deflate stream can
# differ between zlib builds (a Windows author, the Linux runner).
set -eu
cd "$(dirname "$0")/../.."
GUIDE=docs/acceptance/guide
ZIP=$GUIDE/ticketing-acceptance-guide.zip
PY=${PYTHON:-python3}

"$PY" -I "$GUIDE/build/build.py"

fail=0
if ! git diff --exit-code --stat -- "$GUIDE/" ":(exclude)$ZIP"; then
	git diff -- "$GUIDE/" ":(exclude)$ZIP" | head -200
	fail=1
fi
untracked=$(git ls-files --others --exclude-standard -- "$GUIDE/")
if [ -n "$untracked" ]; then
	echo "$untracked" | sed 's/^/untracked: /'
	fail=1
fi
committed=$(mktemp)
trap 'rm -f "$committed"' EXIT
git show "HEAD:$ZIP" >"$committed"
if ! "$PY" -I scripts/ci/zipsame.py "$committed" "$ZIP"; then
	fail=1
fi

if [ "$fail" -ne 0 ]; then
	echo "guide-generated: $GUIDE differs from a fresh 'python -I $GUIDE/build/build.py'; run it and commit the result" >&2
	exit 1
fi
echo "guide-generated: ok"
